package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;

/** A person on a sheet. {@code grades} are their grades (each one of A, B or C) by the date each applies
 *  from, the first from {@link #START} (the beginning of time); {@code version} moves on with each stored edit;
 *  {@code retiredFrom} is the date they are retired from (null while not retired); {@code holds} their holds,
 *  oldest first: their OPEN claims dated within one count in no live total unless a statement bound them, nor do
 *  any of their OPEN claims once the sheet's today reaches their retirement date. */
public class Person {
    /** The from-date of a person's first grade: the beginning of time. */
    public static final LocalDate START = LocalDate.of(1, 1, 1);

    private final long id;
    private final String sheetId;
    private String name;
    private final NavigableMap<LocalDate, String> grades;
    private long version;
    private LocalDate retiredFrom;
    private final List<Hold> holds = new ArrayList<>();
    private LocalDate recordFrom;
    private Integer terms;
    private boolean termsChanged;

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grades = new TreeMap<>(grades);
        this.version = version;
    }

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version,
            LocalDate retiredFrom, List<Hold> holds) {
        this(id, sheetId, name, grades, version);
        this.retiredFrom = retiredFrom;
        this.holds.addAll(holds);
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate on) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(on);
        return e == null ? grades.firstEntry().getValue() : e.getValue();
    }
    /** Every grade by the date it applies from ({@link #START} for the first). */
    public NavigableMap<LocalDate, String> getGrades() { return grades; }
    /** The from-date of the grade the next save records, null when it records none. */
    public LocalDate getRecordFrom() { return recordFrom; }
    public long getVersion() { return version; }
    public LocalDate getRetiredFrom() { return retiredFrom; }
    /** Retired as soon as a date is set, whatever the date. */
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether their retirement date is reached on the date: from then their OPEN (and PENDING) claims count
     *  in no live total unless a statement bound them, as a hold's would. */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }
    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Their holds, oldest first. */
    public List<Hold> getHolds() { return holds; }
    /** Whether a hold of theirs covers the date. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }
    public void addHold(Hold hold) { holds.add(hold); }
    public void setName(String name) { this.name = name; }
    /** Records the grade from the date at the next save, keeping the others. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recordFrom = from;
    }
    /** Their own terms (whole days), null when they have none. */
    public Integer getTerms() { return terms; }
    /** Sets their own terms, noting whether they differ from the ones they had. */
    public void setTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    /** Whether the last {@link #setTerms} changed their terms. */
    public boolean isTermsChanged() { return termsChanged; }
    public void setVersion(long version) { this.version = version; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people kept per sheet, in the order they were added, each with their dated grades. */
@Repository
public class PersonStore {

    private final JdbcTemplate jdbc;

    public PersonStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The people's grades on the sheet (only the one person when {@code personId} is given), by person. */
    private Map<Long, NavigableMap<LocalDate, String>> grades(String sheetId, Long personId) {
        Map<Long, NavigableMap<LocalDate, String>> grades = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId), rs -> {
                    grades.computeIfAbsent(rs.getLong("person_id"), k -> new TreeMap<>())
                            .put(rs.getObject("from_date", LocalDate.class), rs.getString("grade"));
                }, sheetId);
        return grades;
    }

    /** The people's holds on the sheet (only the one person's when {@code personId} is given), by person, oldest first. */
    private Map<Long, List<Hold>> holds(String sheetId, Long personId) {
        Map<Long, List<Hold>> holds = new HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ?"
                + (personId == null ? "" : " AND person_id = " + personId) + " ORDER BY id", rs -> {
                    holds.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(new Hold(
                            rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class)));
                }, sheetId);
        return holds;
    }

    private List<Person> query(String sheetId, Long personId, String sql, Object... args) {
        Map<Long, NavigableMap<LocalDate, String>> grades = grades(sheetId, personId);
        Map<Long, List<Hold>> holds = holds(sheetId, personId);
        RowMapper<Person> row = (rs, i) -> {
            Person p = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                    grades.getOrDefault(rs.getLong("id"), new TreeMap<>()), rs.getLong("version"),
                    rs.getObject("retired_from", LocalDate.class), holds.getOrDefault(rs.getLong("id"), List.of()));
            p.setTerms(rs.getObject("terms", Integer.class));
            return p;
        };
        return jdbc.query(sql, row, args);
    }

    public List<Person> list(String sheetId) {
        return query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? ORDER BY id", sheetId);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = query(sheetId, id, "SELECT * FROM person WHERE sheet_id = ? AND id = ?", sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, ignoring case and the spaces around it; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = query(sheetId, null, "SELECT * FROM person WHERE sheet_id = ? AND name_key = LOWER(?)",
                sheetId, name.trim());
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet (not {@code exceptId}) has this name, ignoring case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(?) AND id <> ?",
                Integer.class, sheetId, name.trim(), exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and no terms of their own. */
    public Person add(String sheetId, String name, String grade) {
        return add(sheetId, name, grade, null);
    }

    /** Adds the person with their first grade, which applies from the beginning of time, and their own
     *  terms (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, terms) VALUES (?, ?, ?)", new String[] { "ID" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setObject(3, terms, java.sql.Types.INTEGER);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)", sheetId,
                id, Person.START, grade);
        Person person = new Person(id, sheetId, name, new TreeMap<>(Map.of(Person.START, grade)), 0);
        person.setTerms(terms);
        return person;
    }

    /**
     * Stores the person over the version it was loaded at, moving the version on; false (nothing
     * stored) when someone else has stored another version since. The grade the edit records (if any)
     * is kept with the ones already recorded, replacing one from the same date.
     */
    public boolean save(Person person) {
        int n = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getSheetId(), person.getId(), person.getVersion());
        if (n == 1) {
            person.setVersion(person.getVersion() + 1);
            LocalDate from = person.getRecordFrom();
            if (from != null) {
                jdbc.update("MERGE INTO person_grade (sheet_id, person_id, from_date, grade) KEY (person_id, from_date)"
                        + " VALUES (?, ?, ?, ?)", person.getSheetId(), person.getId(), from, person.getGrades().get(from));
            }
        }
        return n == 1;
    }

    /** Retires the person from the date. An edit of their name or grade leaves it as it is. */
    public void retire(Person person, LocalDate from) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?", from, person.getSheetId(),
                person.getId());
        person.setRetiredFrom(from);
    }

    /** Adds a hold to the person's holds. An edit of their name or grade leaves them as they are. */
    public void hold(Person person, Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), hold.from(), hold.to());
        person.addHold(hold);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import java.util.function.Function;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The settings kept per sheet, by key. A setting never set, or set blank, has no value. The settings
 *  that carry a figure (the clerk limit, the floor, the cap, the proof threshold, the terms, a grade's terms and the late
 *  percent) are dated: each value is recorded from a from-date, and the value in force on a date is the
 *  one with the latest from-date on or before it (none before every from-date, then the sheet's starting
 *  value). The policy date, the period numbering date, the grace days and the permission matrix are not dated. */
@Repository
public class SettingStore {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String CAP = "cap";

    /** Above it a claim's due needs a proof before it is settled or approved. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    public static final String TERMS = "terms";

    /** The key of a grade's own terms: terms-A, terms-B or terms-C. */
    public static final String TERMS_PREFIX = "terms-";

    /** The grades that may have terms of their own. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    public static final String LATE_PCT = "late-pct";

    public static final String POLICY_DATE = "policy-date";

    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The whole days after its to-date an open period is closed by a new today; blank for off. */
    public static final String GRACE_DAYS = "grace-days";

    /** The key of an action's permission: perm-open, perm-settle, and so on. */
    public static final String PERM_PREFIX = "perm-";

    /** The roles that may take each action while its permission is blank (the standing rule). */
    public static final Map<String, List<Role>> STANDING_PERMS = Map.of(
            "open", List.of(Role.CLERK, Role.STEWARD), "settle", List.of(Role.CLERK, Role.STEWARD),
            "void", List.of(Role.CLERK, Role.STEWARD), "close", List.of(Role.CLERK, Role.STEWARD),
            "reassign", List.of(Role.STEWARD), "reopen", List.of(Role.STEWARD));

    /** The actions of the permission matrix, in the order the screen shows them. */
    public static final List<String> PERM_ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The late percent a sheet has until one is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The terms (days) a sheet has until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** The floor a sheet has until one is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    private final JdbcTemplate jdbc;

    private final SheetStore sheets;

    public SettingStore(JdbcTemplate jdbc, SheetStore sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** Whether the key's values are recorded from a from-date. */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !GRACE_DAYS.equals(key)
                && !key.startsWith(PERM_PREFIX);
    }

    /** Whether the role may take the action (one of {@link #PERM_ACTIONS}): the roles listed in its
     *  permission, else, when blank, the standing rule. */
    public boolean allows(String sheetId, String action, Role role) {
        if (role == Role.VIEWER) {
            return false;
        }
        String value = find(sheetId, PERM_PREFIX + action);
        if (value == null) {
            return STANDING_PERMS.get(action).contains(role);
        }
        return Arrays.stream(value.split(",")).map(String::trim).anyMatch(r -> r.equals(role.shown()));
    }

    /** The permissions recorded, by action; a blank one is null (the standing rule). */
    public Map<String, String> perms(String sheetId) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : PERM_ACTIONS) {
            perms.put(action, find(sheetId, PERM_PREFIX + action));
        }
        return perms;
    }

    /** The setting's value (a dated one's in force on the sheet's today), or null when it has none. */
    public String find(String sheetId, String key) {
        if (isDated(key)) {
            return findOn(sheetId, key, sheets.today(sheetId));
        }
        List<String> found = jdbc.queryForList(
                "SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = ?", String.class,
                sheetId, key);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The dated setting's values recorded, by from-date (a null value is blank). */
    public NavigableMap<LocalDate, String> history(String sheetId, String key) {
        NavigableMap<LocalDate, String> values = new TreeMap<>();
        jdbc.query("SELECT from_date, setting_value FROM sheet_setting_from WHERE sheet_id = ? AND setting_key = ?",
                rs -> {
                    values.put(rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));
                }, sheetId, key);
        return values;
    }

    /** The dated setting's value in force on the date, or null when it has none then. */
    public String findOn(String sheetId, String key, LocalDate date) {
        return on(history(sheetId, key), date);
    }

    private static String on(NavigableMap<LocalDate, String> history, LocalDate date) {
        var entry = date == null ? null : history.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    /** The most a clerk may settle a claim's due at (the one in force on the sheet's today), or null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = find(sheetId, CLERK_LIMIT);
        return value == null ? null : new BigDecimal(value);
    }

    /** The most a person's due-total may be (the one in force on the sheet's today), or null for no cap. */
    public BigDecimal cap(String sheetId) {
        String value = find(sheetId, CAP);
        return value == null ? null : new BigDecimal(value);
    }

    /** The due above which a claim dated on the date needs a proof before it is settled or approved (the
     *  one in force on that date), or null for none. */
    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
        String value = findOn(sheetId, PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The least a claim's live due may be, in force on each date: the floor recorded then, else 1.00. Read once, for many claims. */
    public Function<LocalDate, BigDecimal> floors(String sheetId) {
        return amounts(history(sheetId, FLOOR), DEFAULT_FLOOR);
    }

    /** The percent of an overdue claim's figure charged at each 30-day boundary it is overdue past, in force on each
     *  date: the one recorded then, else 0.00. Read once, for many claims. */
    public Function<LocalDate, BigDecimal> latePcts(String sheetId) {
        return amounts(history(sheetId, LATE_PCT), DEFAULT_LATE_PCT);
    }

    private static Function<LocalDate, BigDecimal> amounts(NavigableMap<LocalDate, String> history,
            BigDecimal starting) {
        return date -> {
            String value = on(history, date);
            return value == null ? starting : new BigDecimal(value);
        };
    }

    /** The due-total at most the cap (none when null). */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return cap != null && dueTotal.compareTo(cap) > 0 ? cap.setScale(2) : dueTotal;
    }

    /** The days after its date a claim is due by, in force on the date: the terms recorded then, else 14. */
    public int terms(String sheetId, LocalDate date) {
        String value = findOn(sheetId, TERMS, date);
        return value == null ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms (days) in force on the date, or null when it has none then (then the sheet's terms). */
    public Integer gradeTerms(String sheetId, String grade, LocalDate date) {
        String value = findOn(sheetId, TERMS_PREFIX + grade, date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The days after its date a claim of a person of the grade is due by, in force on the date: the
     *  grade's own terms, else the sheet's. */
    public int terms(String sheetId, String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTerms(sheetId, grade, date);
        return own == null ? terms(sheetId, date) : own;
    }

    /** The date the sheet's rounding turns on, or null when blank (then the sheet's today). */
    public LocalDate policyDate(String sheetId) {
        String value = find(sheetId, POLICY_DATE);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The date from which claims opened are numbered per period, or null when blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The whole days after its to-date an open period is closed by a new today, or null when blank (off). */
    public Integer graceDays(String sheetId) {
        String value = find(sheetId, GRACE_DAYS);
        return value == null ? null : Integer.valueOf(value);
    }

    /** Records the setting's value; a dated one's from the date (replacing a value recorded from it). */
    public void set(String sheetId, String key, String value, LocalDate from) {
        if (isDated(key)) {
            jdbc.update("MERGE INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value) "
                    + "KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)", sheetId, key, from, value);
            return;
        }
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) "
                + "VALUES (?, ?, ?)", sheetId, key, value);
    }
}

